import sys
from functools import cmp_to_key

def parse_input(data):
    lines = data.strip().split('\n')
    k, n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    improvements = []
    for i in range(n):
        parts = list(map(int, lines[2 + i].split()))
        t, idx, b = parts
        improvements.append({
            'type': t,
            'skill': idx - 1,  # 0-indexed
            'value': b,
            'index': i + 1
        })

    return k, n, m, a, improvements

def product_after(a, improvement):
    """Calculate product of all skills if we apply this improvement"""
    skill_idx = improvement['skill']

    if improvement['type'] == 1:  # assign
        a[skill_idx] = improvement['value']
    elif improvement['type'] == 2:  # add
        a[skill_idx] += improvement['value']
    elif improvement['type'] == 3:  # multiply
        a[skill_idx] *= improvement['value']

    prod = 1
    for x in a:
        prod *= x

    # Restore original value
    old_val = a[skill_idx]
    if improvement['type'] == 1:
        pass  # can't restore since it was assigned
    elif improvement['type'] == 2:
        a[skill_idx] -= improvement['value']
    elif improvement['type'] == 3:
        a[skill_idx] = old_val  # This won't work correctly

    return prod

def simple_greedy(k, n, m, a, improvements):
    """Simple greedy approach"""
    a = a.copy()
    used = [False] * n
    selected = []

    for _ in range(m):
        max_improvement = -1
        best_idx = -1

        for i in range(n):
            if used[i]:
                continue

            old_val = a[improvements[i]['skill']]

            if improvements[i]['type'] == 1:
                a[improvements[i]['skill']] = improvements[i]['value']
            elif improvements[i]['type'] == 2:
                a[improvements[i]['skill']] += improvements[i]['value']
            elif improvements[i]['type'] == 3:
                a[improvements[i]['skill']] *= improvements[i]['value']

            prod = 1
            for x in a:
                prod *= x

            if used[i] or (best_idx != -1 and prod <= max_improvement):
                pass

            # Actually let's recalculate properly
            best_idx = i
            max_improvement = prod

            if improvements[i]['type'] == 1:
                a[improvements[i]['skill']] = improvements[i]['value']
            elif improvements[i]['type'] == 2:
                a[improvements[i]['skill']] += improvements[i]['value']
            elif improvements[i]['type'] == 3:
                a[improvements[i]['skill']] *= improvements[i]['value']

    return selected

def solve_basic(k, n, m, a, improvements):
    """Basic solution - test simple greedy"""
    if m == 0:
        return "0\n"

    a = a.copy()
    used = [False] * n
    selected = []

    for _ in range(m):
        best_gain = -float('inf')
        best_idx = -1

        for i in range(n):
            if used[i]:
                continue

            old_skill = a[improvements[i]['skill']]
            new_skill = old_skill

            t = improvements[i]['type']
            b = improvements[i]['value']

            if t == 1:
                new_skill = b
            elif t == 2:
                new_skill = old_skill + b
            elif t == 3:
                new_skill = old_skill * b

            if new_skill >= 0:
                # Calculate product ratio (assuming positive values)
                ratio = 1
                for skill_idx, val in enumerate(a):
                    if improvements[i]['skill'] == skill_idx:
                        ratio *= val
                ratio /= (1 if val == 0 else val)  # Simplified

                # Just use the new skill value as proxy for benefit
                gain = new_skill - old_skill if t == 2 else abs(new_skill - old_skill) if old_skill > 0 else new_skill
            else:
                gain = 0

            if gain > best_gain:
                best_gain = gain
                best_idx = i

        if best_idx != -1:
            used[best_idx] = True
            selected.append(best_idx)

            t = improvements[best_idx]['type']
            b = improvements[best_idx]['value']
            skill_idx = improvements[best_idx]['skill']

            if t == 1:
                a[skill_idx] = b
            elif t == 2:
                a[skill_idx] += b
            elif t == 3:
                a[skill_idx] *= b

    return len(selected), [x + 1 for x in selected]

def main():
    # Read from input
    input_data = sys.stdin.read()

    k, n, m, a, improvements = parse_input(input_data)

    # For large inputs or many improvements, use greedy
    # Sort improvements by their potential effect

    solution_len, solution_indices = solve_basic(k, n, m, a, improvements)

    output = f"{solution_len}\n"
    output += " ".join(map(str, solution_indices)) + " "
    return output

if __name__ == "__main__":
