def solution(s):
    """
    Solve the problem of finding the maximum number of chessmen that can be placed
    on an n×m board where each placement consists of two cells at Manhattan distance exactly 3.
    """
    n, m = map(int, s.split())

    # If the board is 1 row or 1 column, we can only pair cells in groups of 4 columns
    # So the answer is floor(n * m / 2)
    if n == 1 or m == 1:
        return str(n * m // 2)

    # For small boards (2x2, 2x3, 3x2), we can't form any pairs with distance 3
    # This is because the maximum Manhattan distance on such boards is less than 3
    elif n * m <= 4:
        return str(0)

    # For larger boards, we can almost always fill all or all but 1 or 2 cells
    # If odd total cells, we lose 1 (can't place perfectly on odd board)
    # If even total cells on sufficiently large boards, we lose 2
    total = n * m
    if total % 2 == 1:
        return str(total - 1)
    else:
        return str(total - 2)

