import sys
from collections import deque

sys.setrecursionlimit(2000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        edges.append((parts[0], parts[1], parts[2], i + 1))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v, w, idx in edges:
        adj[u].append((v, w, idx))
        adj[v].append((u, w, idx))

    def check_disconnected(limit):
        """Check if s and t are disconnected after removing edges in removed_idx"""
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            u = queue.popleft()
            if u == t:
                return False
            for v, w, idx in adj[u]:
                if idx not in removed_idx and not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return True

    def shortest_path_cost(removed_idx):
        """Find shortest path from s to t using BFS, skipping removed edges"""
        if check_disconnected(removed_idx):
            return None  # Already disconnected

        # BFS with edge weights to find minimum cost path
        INF = float('inf')
        dist = [INF] * (n + 1)
        dist[s] = 0
        queue = deque([s])

        while queue:
            u = queue.popleft()
            if u == t:
                return dist[t]
            for v, w, idx in adj[u]:
                if idx not in removed_idx and dist[v] == INF:
                    dist[v] = dist[u] + w
                    queue.append(v)
        return INF

    def get_path_via_bfs(removed_idx):
        """Get a valid path from s to t to collect edges on it"""
        if check_disconnected(removed_idx):
            return None

        visited = [False] * (n + 1)
        parent = [None] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            u = queue.popleft()
            if u == t:
                break
            for v, w, idx in adj[u]:
                if idx not in removed_idx and not visited[v]:
                    visited[v] = True
                    parent[v] = (u, idx)
                    queue.append(v)

        if not visited[t]:
            return None

        path = []
        curr = t
        while curr != s:
            _, idx = parent[curr]
            path.append(idx)
            curr = parent[curr][0]
        return path

    # Check if already disconnected
    if check_disconnected(set()):
        return "0\n0\n"

    # Try removing 1 edge
    for u, v, w, idx in edges:
        if check_disconnected({idx}):
            min_cost = w
            result_idx = [idx]
            return f"{min_cost}\n1\n{' '.join(map(str, result_idx))}\n"

    # Build minimum cost path first
    INF = float('inf')
    distances = [INF] * (n + 1)
    distances[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v, w, idx in adj[u]:
            if distances[v] == INF:
                distances[v] = distances[u] + w
                queue.append(v)

    # If path exists
    if distances[t] < INF:
        min_cost = distances[t]
        result_idx = get_path_via_bfs(set())
        if result_idx:
            return f"{min_cost}\n1\n{' '.join(map(str, result_idx))}\n"

    # Try removing 2 edges
    # Strategy: For each edge, try removing it, then check if the resulting path
    # has an edge we can also remove

    best_cost = INF
    best_pair = None

    for i, (u1, v1, w1, idx1) in enumerate(edges):
        # Remove edge i
        remaining = {idx1}
        if check_disconnected(remaining):
            min_cost = w1
            if min_cost < best_cost:
                best_cost = min_cost
                best_pair = (idx1)

        # Get path from s to t after removing edge i
        path = get_path_via_bfs(remaining)
        if path is None:
            # Already disconnected
            if min_cost < best_cost:
                best_cost = min_cost
                best_pair = (idx1)
            continue

        # Try removing one more edge from the path or any edge
        for idx2 in path:
            if idx2 != idx1:
                remaining2 = {idx1, idx2}
                # Check if this disconnects s and t
                if check_disconnected(remaining2):
                    # Cost is sum of weights
                    cost = w1
                    for j, (u2, v2, w2, idx2b) in enumerate(edges):
                        if idx2b == idx2:
                            cost += w2

                    if cost < best_cost:
                        best_cost = cost
                        best_pair = (idx1, idx2)

    if best_pair is None:
        return "-1\n"

    return f"{best_cost}\n2\n{' '.join(map(str, best_pair))}\n"

