def is_geometric(arr):
    n = len(arr)
    if n <= 2:
        return True

    # If first element is 0, all must be 0 for a valid GP
    if arr[0] == 0:
        return all(x == 0 for x in arr)

    # Check ratios using cross-multiplication to avoid floating point issues
    # For GP: arr[i] / arr[i-1] = arr[1] / arr[0] for all i
    # Cross multiply: arr[i] * arr[0] == arr[i-1] * arr[1]
    for i in range(1, n):
        if arr[i] * arr[0] != arr[i - 1] * arr[1]:
            return False

    return True


