        improved = False

        for i in range(n):
            if matching[i] == -1:
                continue

            for j in range(n):
                if i == j:
                    continue
                if matching[j] != i:
                    # Check if both would prefer to switch
                    if cost_matrix[i][j] < cost_matrix[i][matching[i]] and \
                       cost_matrix[j][i] < cost_matrix[j][matching[j]]:
                        # Propose and switch
                        matching[i] = j
                        matching[j] = i

