    # Compute exponents using matrix exponentiation
    # For f1, f2, f3 coefficients, they each follow the same recurrence: e_n = e_{n-1} + e_{n-2} + e_{n-3}

    def compute_exponential(n, init_vals, mod):
        """Given initial values [e1, e2, e3] for terms 1,2,3 return e_n."""
        # Build 12x12 matrix or simpler: 4x4 matrix for [e_n, e_{n-1}, e_{n-2}, e_{n-3}]
        init = [init_vals[3], init_vals[2], init_vals[1], init_vals[0]]
        mat = [[0]*4 for _ in range(4)]
        mat[0][0] = mat[0][1] = mat[0][2] = 1
        mat[1][0] = 1
        mat[2][1] = 1
        mat[3][2] = 1
        steps = n - 4
        result_mat = matrix_pow(mat, steps, mod)
        res = 0
        for j in range(4):
            res = (res + result_mat[0][j] * init[j]) % mod
        return res

    # For c coefficient, we have e_n = e_{n-1} + e_{n-2} + e_{n-3} + 2n - 6
    # This requires a 6x6 matrix to track linear and constant terms
    def compute_c_exp(n, mod):
        # State: [c_n, c_{n-1}, c_{n-2}, n, 1]
        # Transition: c_{n+1} = c_n + c_{n-1} + c_{n-2} + 2(n+1) - 6 = c_n + c_{n-1} + c_{n-2} + 2n - 4
        # Initial state at n=4: [c_4=2, c_3=0, c_2=0, n=4, 1]
        state = [2 % mod, 0, 0, 4, 1]
        mat = [[0]*5 for _ in range(5)]
        mat[0][0] = mat[0][1] = mat[0][2] = 1  # add c terms
        mat[0][3] = 2  # add 2*n
        mat[0][4] = -4 % mod  # subtract 4

        mat[1][0] = 1  # c_{n} = previous c_{n+1}
        mat[2][1] = 1  # c_{n-1} = previous c_n
        mat[3][3] = 1  # n stays
        mat[3][4] = 1  # add 1

        mat[4][4] = 1  # constant 1 stays

        steps = n - 4
        if steps <= 0:
            return state[0]
        mat_res = matrix_pow(mat, steps, mod)
        res = 0
        for j in range(5):
            res = (res + mat_res[0][j] * state[j]) % mod
        return res

    exp_f1 = compute_exponential(n, [1, 0, 0, 1], MOD)  # f1: [e_1, e_2, e_3, e_4]
    exp_f2 = compute_exponential(n, [0, 1, 0, 1], MOD)  # f2: [e_1, e_2, e_3, e_4]
    exp_f3 = compute_exponential(n, [0, 0, 1, 1], MOD)  # f3: [e_1, e_2, e_3, e_4]
    exp_c = compute_c_exp(n, MOD)

    ans = pow(f1, exp_f1, MOD)
    ans = (ans * pow(f2, exp_f2, MOD)) % MOD
    ans = (ans * pow(f3, exp_f3, MOD)) % MOD
    ans = (ans * pow(c, exp_c, MOD)) % MOD

    return str(ans)

