def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines[0]:
        return "1\n1 "

    n, m = map(int, lines[0].split())

    # Read ice cream sets at each vertex
    vertex_ice_creams = []  # 0-indexed: vertex i (1-based) -> vertex_ice_creams[i-1]
    idx = 1
    for i in range(n):
        parts = list(map(int, lines[idx].split()))
        idx += 1
        si = parts[0]
        if si == 0:
            vertex_ice_creams.append([])
        else:
            vertex_ice_creams.append(parts[1:])

    # Read tree edges and build adjacency list
    tree = [[] for _ in range(n + 1)]
    for i in range(n - 1):
        u, v = map(int, lines[idx].split())
        idx += 1
        tree[u].append(v)
        tree[v].append(u)

    # BFS to get vertex processing order
    bfs_order = []
    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True

    while queue:
        u = queue.popleft()
        bfs_order.append(u)
        for v in tree[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

    # For each type, track which vertex in BFS order it first appears at
    type_first_bfs_vertex = [-1] * (m + 1)  # 1-indexed types
    for v in bfs_order:
        v_idx = v - 1  # 0-indexed into vertex_ice_creams
        for t in vertex_ice_creams[v_idx]:
            if type_first_bfs_vertex[t] == -1:
                type_first_bfs_vertex[t] = v

    # colors[t] stores the color assigned to type t (1-indexed)
    colors = [0] * (m + 1)

    # Track types assigned at each vertex for conflict checking within current processing
    # Process each vertex in BFS order
    for v in bfs_order:
        v_idx = v - 1
        types = vertex_ice_creams[v_idx]

        if not types:
            continue

        # Find all types at this vertex and their colors
        # Types that are already colored must be respected
        # Types that are uncolored need to be assigned colors

        # Use a mapping of type -> actual color for this vertex
        type_colors_at_vertex = {}
        for t in types:
            c = colors[t]
            type_colors_at_vertex[t] = c

        # Now assign colors to types that don't have them yet
        used_colors = set()
        for t in types:
            if colors[t] == 0:
                # Need to assign color
                # Try colors starting from 1, skipping those already used at this vertex
                c = 1
                while True:
                    # Check if this color conflicts with any already-colored type at this vertex
                    conflict = False
                    for other_t in types:
                        if colors[other_t] == 0:
                            continue  # other types we're about to assign
                        if other_t != t and colors[other_t] == c:
                            conflict = True
                            break

                    if not conflict:
                        colors[t] = c
                        used_colors.add(c)
                        break
                    c += 1

    # Find maximum color used
    max_col = 0
    for i in range(1, m + 1):
        if colors[i] > 0:
            max_col = max(max_col, colors[i])
        elif max_col == 0 and i <= m:
            max_col = 1

    # Output result
    result_lines = [str(max_col)]
    if m > 0:
        result_lines.append(' '.join(map(str, colors[1:])))
    else:
        result_lines.append("")

    return '\n'.join(result_lines)


