def solution(input_str):
    n, p, l, r = map(int, input_str.split())
    mod = p

    # Precompute factorials and their modular inverses
    fact = [1] * (n + 1)

    def ext_gcd(a, b):
        if a == 0:
            return b, 0, 1
        g, x1, y1 = ext_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return g, x, y

    def mod_inv(a, m):
        if a == 0:
            return 0
        g, x, y = ext_gcd(a % m, m)
        if g != 1:
            return 0
        return x % m

    # Compute factorials
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % mod

    # Compute inverse factorials
    inv = [1] * (n + 1)
    if mod != 1:
        inv[n] = mod_inv(fact[n], mod)
        for i in range(n - 1, -1, -1):
            inv[i] = (inv[i + 1] * (i + 1)) % mod

    def nCr(n_val, r_val):
        if r_val < 0 or r_val > n_val:
            return 0
        return fact[n_val] * inv[r_val] % mod * inv[n_val - r_val] % mod

    ans = 0

    # Iterate over all possible counts of A and B customers
    # with constraint that A >= B (since we start with 0 notes and can't
    # serve a B before an A)
    for a in range(n + 1):
        max_b = min(a, n - a)
        for b in range(max_b + 1):
            diff = a - b  # Final 50-yuan notes
            if l <= diff <= r:
                c = n - a - b  # Number of C customers

                # Number of valid AB sequences (ballot theorem)
                if a + b > 0:
                    valid_ab = (nCr(a + b, a) - nCr(a + b, a - 1)) % mod
                else:
                    valid_ab = 1

                # If no customers, they must start at diff=0
                if a == 0 and b == 0:
                    valid_ab = 1 if diff == 0 else 0

                # Ways to insert C customers into the sequence
                ways = (valid_ab * nCr(n, c)) % mod
                ans = (ans + ways) % mod

    return str(ans)

def solution(input_str):
    n, k = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    def power(a, b):
        result = 1
        a %= MOD
        while b:
            if b & 1:
                result = result * a % MOD
            a = a * a % MOD
            b >>= 1
        return result

    def modinv(a):
        return power(a, MOD - 2)

    # Special case: k = 1 means only 1 string, all characters the same
    if k == 1:
        return str((n - 1) ** 2 % MOD)

    k_inv = modinv(k % MOD)

    # E[f(s)^2] = sum E[Y_i] + 2*sum E[Y_i * Y_j] for i < j
    # E[Y_i] = k^{-(n-i)}
    # E[Y_i * Y_j] = k^{-max(j, n-i)}

    total = 0

    # First sum: diagonal terms (i = j)
    for i in range(1, n):
        exp = n - i
        total = (total + power(k_inv, exp)) % MOD

    # Second sum: off-diagonal terms (i < j), multiplied by 2 since order matters
    for i in range(1, n):
        for j in range(i + 1, n):
            exp = max(j, n - i)
            total = (total + power(k_inv, exp)) % MOD
        total = total * 2 % MOD

    return str(total)

