        if i < len(lines) and lines[i]:
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)
            edge_list.append((u, v))

    # Tarjan's bridge-finding algorithm
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    timer = [0]
    bridges = []

    def dfs_bridge(u, p=-1):
        disc[u] = low[u] = timer[0]
        timer[0] += 1
        for v in adj[u]:
            if v == p:
                continue
            if disc[v] != -1:
                low[u] = min(low[u], disc[v])
            else:
                dfs_bridge(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))

    dfs_bridge(1, -1)

    if len(bridges) > 0:
        return '0\n'

    # No bridges → graph is 2-edge-connected
    # DFS tree orientation: tree edges from parent to child, back edges from node to ancestor
    disc_b = [-1] * (n + 1)
    timer_b = [0]
    visited_edge = set()

    def dfs_orient(u, p=-1):
        disc_b[u] = timer_b[0]
        timer_b[0] += 1
        for v in adj[u]:
            if disc_b[v] != -1 and disc_b[u] < disc_b[v]:
                # Back edge to ancestor (already considered)
                if (u, v) not in visited_edge:
                    visited_edge.add((u, v))
            elif v == p:
                continue
            else:
                # Tree edge to child or back edge
                dfs_orient(v, u)

    dfs_orient(1)

    # For each edge, orient based on discovery time
    result = []
    for u, v in edge_list:
        if disc_b[u] < disc_b[v]:
            result.append((u, v))
        else:
            result.append((v, u))

    return '\n'.join(f"{u} {v}" for u, v in result) + '\n'


