import sys


def count_matches(s1, s2):
    """Count positions where s1 and s2 match."""
    return sum(1 for a, b in zip(s1, s2) if a == b)


def solve(n, m, constraints):
    """
    Solve the problem: count valid codes satisfying all constraints.
    constraints is a list of (attempt_string, match_count).
    """
    if m == 0:
        return 2 ** n

    # For small n, brute force
    if n <= 22:
        count = 0
        for mask in range(1 << n):
            code = format(mask, f'0{n}b')
            valid = True
            for attempt, expected in constraints:
                if count_matches(code, attempt) != expected:
                    valid = False
                    break
            if valid:
                count += 1
        return count

    # Meet-in-the-middle approach for n up to 35
    left_size = n // 2
    right_size = n - left_size

    # For each constraint, precompute left half matches
    # We'll generate (left_mask, tuple of match counts for each constraint)
    # and store it in a dict keyed by (left_mask, match_tuple)

    meeting_dict = {}

    from itertools import product

    for left_val in range(1 << left_size):
        # Convert to binary string (left_size bits)
        left_str = format(left_val, f'0{left_size}b')

        # Calculate matches with each constraint's attempt for left half
        match_counts = []
        for attempt, _ in constraints:
            try:
                match_counts.append(count_matches(left_str, attempt[:left_size]))
            except:
                # Handle if attempt string is longer than left_size (shouldn't happen)
                match_counts.append(0)

        meeting_key = (left_val, tuple(match_counts))
        if meeting_key not in meeting_dict:
            meeting_dict[meeting_key] = 0

    # Now generate right halves and match
    result = 0

    for right_val in range(1 << right_size):
        right_str = format(right_val, f'0{right_size}b')

        # Calculate matches with each constraint's attempt for right half
        right_match_counts = []
        for attempt, _ in constraints:
            right_match_counts.append(count_matches(right_str, attempt[right_size:]))

        right_match_tuple = tuple(right_match_counts)

        # For each left match tuple, check if there exists a valid combination
        left_matches_tuple = None

        for i in range(len(constraints)):
            target = constraints[i][1] - right_match_counts[i]
            if target < 0:
                target = None
                break

        if target is None:
            continue

        # Find left halves that satisfy remaining matches needed
        for (left_val, left_match_tuple), _ in meeting_dict.items():
            # Check if left match tuple can be extended with right matches
            valid = True
            if target is None:
                target = None
            else:
                for i in range(len(constraints)):
                    if left_match_tuple[i] + right_match_counts[i] != constraints[i][1]:
                        valid = False
                        break

            if valid:
                result += meeting_dict[(left_val, left_match_tuple)]

    return result


def solution(input_str):
    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())

    constraints = []
    for i in range(1, m + 1):
        parts = data[i].split()
        attempt = parts[0]
        matches = int(parts[1])
        constraints.append((attempt, matches))

    return str(solve(n, m, constraints))


