    def dist_sq(a, b):
        return (a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2

    def dist(a, b):
        return math.sqrt(dist_sq(a, b))

    cum_dist = [0.0] * (n + 1)
    for i in range(n):
        cum_dist[i+1] = cum_dist[i] + dist(points[i], points[i+1])

    best_time = float('inf')
    best_point = None

    # Precompute velocity ratio
    k = vp / vs

    # Add point list P as a list for indexing
    P = [float(v) for v in P]

    for i in range(n):
        A = points[i]
        B = points[i+1]
        L = dist(A, B)
        D_A = cum_dist[i]

        # If L is 0, skip (but problem says consecutive points don't coincide)
        if L < 1e-9:
            continue

        PA_x, PA_y, PA_z = [P[j] - A[j] for j in range(3)]
        BA_x, BA_y, BA_z = [B[j] - A[j] for j in range(3)]

        PA_sq_magnitude = PA_x*PA_x + PA_y*PA_y + PA_z*PA_z
        dot_product = PA_x*BA_x + PA_y*BA_y + PA_z*BA_z
        BA_sq_magnitude = BA_x*BA_x + BA_y*BA_y + BA_z*BA_z  # = L^2

        k2 = k * k

        # a*u^2 + b*u + c <= 0
        a = BA_sq_magnitude - k2 * L * L
        b = -2 * dot_product - 2 * k2 * D_A * L
        c = PA_sq_magnitude - k2 * D_A * D_A

        discriminant = b*b - 4*a*c

        if abs(a) < 1e-15:
            # Linear case
            if b < 1e-15:
                if c <= 1e-9:
                    u_candidates = [0.0, 1.0]
                    for u in u_candidates:
                        t = (D_A + u * L) / vs
                        if t < best_time and t >= 1e-9:
                            best_time = t
                            best_point = [A[0]+u*BA_x, A[1]+u*BA_y, A[2]+u*BA_z]
            else:
                # u = -c/b, must have b*u + c <= 0
                u_opt = -c / b
                if 0 <= u_opt <= 1:
                    if abs(a * u_opt*u_opt + b * u_opt + c) <= 1e-9:
                        t = (D_A + u_opt * L) / vs
                        if t < best_time:
                            best_time = t
                            best_point = [A[0]+u_opt*BA_x, A[1]+u_opt*BA_y, A[2]+u_opt*BA_z]
        elif discriminant < 0:
            pass
        elif discriminant <= 1e-9:
            u = -b / (2*a)
            if 0 <= u <= 1:
                t = (D_A + u * L) / vs
                if t < best_time:
                    best_time = t
                    best_point = [A[0]+u*BA_x, A[1]+u*BA_y, A[2]+u*BA_z]
        else:
            sqrt_disc = math.sqrt(discriminant)
            u1 = (-b - sqrt_disc) / (2*a) if a > 0 else (-b + sqrt_disc) / (2*a)
            u2 = (-b + sqrt_disc) / (2*a) if a > 0 else (-b - sqrt_disc) / (2*a)

            # Check u1 and u2 if in [0,1]
            def check(u):
                if 0 <= u <= 1:
                    if abs(a*u*u + b*u + c) <= 1e-9:
                        t = (D_A + u * L) / vs
                        if t < best_time:
                            return t, [A[0]+u*BA_x, A[1]+u*BA_y, A[2]+u*BA_z]
                return None

            candidates = [u1, u2]
            # Check 0 and 1
            candidates.append(0.0)
            candidates.append(1.0)

            for u in candidates:
                result = check(u)
                # Also check just inside interval for a < 0 (valid between roots) or a > 0 (outside roots)
                if u1 <= 0 <= u2:
                    result = check(0.0)
                if u1 <= 1 <= u2:
                    result = check(1.0)

    if best_time == float('inf'):
        return "NO"
    else:
        return f"YES\n{best_time:.15f}\n{best_point[0]:.15f} {best_point[1]:.15f} {best_point[2]:.15f}"

