        if line_idx + 1 >= len(lines):
            break

        parts = lines[line_idx].split()
        a, b = int(parts[0]), int(parts[1])
        s = lines[line_idx + 1]

        n = len(s)
        max_size = n + 1

        # Find consecutive blocks of '.'
        dots = []
        consecutive = 0
        for char in s:
            if char == '.':
                consecutive += 1
            else:
                if consecutive > 0:
                    dots.append(consecutive)
                consecutive = 0
        if consecutive > 0:
            dots.append(consecutive)

        # Alice wins if she can make a valid move and the XOR sum is non-zero
        can_alice_move = any(k >= a for k in dots)

        if not can_alice_move:
            results.append("NO")
            continue

        # Compute Grundy values using dynamic programming
        grundy = [0] * max_size

        for size in range(1, max_size):
            if size < b:
                continue

            reachable = set()

            # Alice can move on this block
            if size >= a:
                for start in range(size - a + 1):
                    left = start
                    right = size - a - start
                    reachable.add(grundy[left] ^ grundy[right])

            # Bob can also move on this block
            if size >= b:
                for start in range(size - b + 1):
                    left = start
                    right = size - b - start
                    reachable.add(grundy[left] ^ grundy[right])

            # Compute mex
            g = 0
            while g in reachable:
                g += 1
            grundy[size] = g

        # Compute XOR sum of all blocks
        xor_sum = 0
        for k in dots:
            xor_sum ^= grundy[k]

        results.append("YES" if xor_sum > 0 else "NO")

    return '\n'.join(results)
